// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address constant OWNER = address(0xA11CE);

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != OWNER);
        // A non-owner caller must NOT be able to transfer ownership.
        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "non-owner must not transfer ownership");
    }
}
